mapper.select:
select id, message_id, user_address, token_symbol, token_address,
       from_chain_id, to_chain_id, source_tx_hash, created_at
from ccip_bridge_record
where user_address = #{userAddress}
order by created_at desc
limit #{limit}

mapper.update:
update ccip_bridge_record
set updated_at = now()
where id = #{id, typeHandler=com.dripswap.bff.repository.typehandler.UuidTypeHandler}
